{
  "name": "@codemem/opencode-plugin",
  "version": "0.48.1",
  "description": "CodeMem plugin for OpenCode",
  "type": "module",
  "main": "./index.js",
  "types": "./index.d.ts",
  "exports": {
    ".": {
      "types": "./index.d.ts",
      "import": "./index.js"
    },
    "./rpc": {
      "types": "./rpc.d.ts",
      "import": "./rpc.js"
    },
    "./tui": {
      "types": "./tui.d.ts",
      "import": "./tui.js"
    }
  },
  "files": [
    "index.js",
    "index.d.ts",
    "rpc.js",
    "rpc.d.ts",
    "tui.js",
    "tui.d.ts",
    "src/opencode-v2-contract-fixture.ts",
    "v2-contract-fixture/",
    "README.md",
    "LICENSE",
    ".opencode/package.json",
    ".opencode/plugins/",
    ".opencode/lib/"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "1.19.5",
    "@opencode/plugin": "2.0.24"
  },
  "devDependencies": {
    "codemem": "^0.48.1",
    "@opencode/cli": "2.0.24",
    "@types/node": "^24.12.4",
    "vitest": "^4.1.11"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/kunickiaj/codemem.git",
    "directory": "packages/opencode-plugin"
  },
  "homepage": "https://github.com/kunickiaj/codemem",
  "bugs": {
    "url": "https://github.com/kunickiaj/codemem/issues"
  },
  "engines": {
    "node": ">=24.15.0",
    "opencode": ">=1.18.29"
  },
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "codemem",
    "memory",
    "ai",
    "coding",
    "agent",
    "opencode",
    "plugin"
  ],
  "scripts": {
    "test": "pnpm exec vitest run",
    "test:opencode-v2-contract": "node ./scripts/packed-v2-host-smoke.mjs",
    "test:native-memory-tools-host": "node ./scripts/native-memory-tools-host-smoke.mjs",
    "test:packed-artifact": "pnpm --filter codemem build && node ./scripts/packed-artifact-smoke.mjs",
    "test:packed-artifact:prepared": "node ./scripts/packed-artifact-smoke.mjs"
  }
}
